WITH RecentOrderItems AS (SELECT * FROM order_items WHERE product_id = 34), order_items_stats AS (SELECT product_id, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, MAX(quantity) AS max_quantity, SUM(unit_price * quantity) AS revenue FROM RecentOrderItems GROUP BY product_id, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END) SELECT * FROM order_items_stats ORDER BY product_id DESC
